"""
apply.py — executes all system configuration changes for BulwarkOS OOBE.

Each step is a self-contained function returning (success: bool, message: str).
Steps are run sequentially; a failure is recorded but does not abort later steps
unless they have a hard dependency (noted inline).

All commands that modify system state use pkexec / polkit for privilege escalation
rather than requiring the wizard itself to run as root.
"""

import os
import subprocess
import shutil
from pathlib import Path
from typing import Callable

from ..state import WizardState


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

STATE_FILE = "/var/lib/bulwarkos/.setup-complete"
MODPROBE_CONF = "/etc/modprobe.d/bulwarkos-vfio.conf"
DRACUT_CONF = "/etc/dracut.conf.d/bulwarkos-vfio.conf"
VM_TEMPLATE_DIR  = "/usr/share/bulwarkos/vm-templates"
NET_TEMPLATE_DIR = "/usr/share/bulwarkos/net-templates"

# Canonical virsh invocation used by all steps.
# --connect qemu:///system  — always targets the system libvirt instance
#                             explicitly, regardless of the calling user's
#                             default URI, so domains and networks are
#                             registered system-wide (needed for autostart
#                             at boot before any user session exists).
# pkexec                    — required because the wizard runs as a normal
#                             user whose libvirt group membership won't be
#                             active until after the reboot at end of setup.
_VIRSH = ["pkexec", "virsh", "--connect", "qemu:///system"]


def _run(cmd: list[str], timeout: int = 120) -> tuple[bool, str]:
    """Run a command, return (success, output/error)."""
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=timeout,
        )
        if result.returncode == 0:
            return True, result.stdout.strip()
        return False, (result.stderr or result.stdout).strip()
    except subprocess.TimeoutExpired:
        return False, f"Command timed out after {timeout}s: {' '.join(cmd)}"
    except FileNotFoundError:
        return False, f"Command not found: {cmd[0]}"


def _write_file_as_root(path: str, content: str) -> tuple[bool, str]:
    """
    Write a file to a system path using a small pkexec helper script.
    In production this would use a polkit-protected D-Bus service;
    here we use a tmpfile + pkexec tee approach for simplicity.
    """
    import tempfile
    try:
        with tempfile.NamedTemporaryFile(mode="w", suffix=".conf", delete=False) as tmp:
            tmp.write(content)
            tmp_path = tmp.name
        ok, msg = _run(["pkexec", "cp", tmp_path, path])
        os.unlink(tmp_path)
        if ok:
            _run(["pkexec", "chmod", "644", path])
        return ok, msg
    except OSError as e:
        return False, str(e)


# ---------------------------------------------------------------------------
# Step 1 — kernel arguments (IOMMU)
# ---------------------------------------------------------------------------

def step_kargs(state: WizardState) -> tuple[bool, str]:
    """
    Appends IOMMU kernel arguments to the current rpm-ostree deployment.
    Skipped if all required kargs are already present in /proc/cmdline.
    """
    vendor = state.hardware.cpu_vendor
    if vendor == "intel":
        iommu_arg = "intel_iommu=on"
    elif vendor == "amd":
        iommu_arg = "amd_iommu=on"
    else:
        return False, f"Unknown CPU vendor '{vendor}' — cannot set IOMMU karg."

    try:
        cmdline = Path("/proc/cmdline").read_text()
        needed = [iommu_arg, "iommu=pt", "rd.driver.pre=vfio-pci"]
        if all(arg in cmdline for arg in needed):
            return True, "Kernel arguments already present — skipped."
    except OSError:
        pass

    cmd = [
        "pkexec", "rpm-ostree", "kargs",
        f"--append-if-missing={iommu_arg}",
        "--append-if-missing=iommu=pt",
        "--append-if-missing=rd.driver.pre=vfio-pci",
    ]
    return _run(cmd, timeout=60)


# ---------------------------------------------------------------------------
# Step 2 — modprobe.d VFIO config
# ---------------------------------------------------------------------------

def step_modprobe(state: WizardState) -> tuple[bool, str]:
    """
    Writes /etc/modprobe.d/bulwarkos-vfio.conf with the PCI IDs of all
    devices selected for passthrough (NICs + optional GPU).
    """
    ids: list[str] = []

    for nic in state.selected_nics:
        # vendor_id is already in "xxxx:yyyy" form
        ids.append(nic.vendor_id)

    if state.gpu_passthrough and state.selected_gpu:
        ids.append(state.selected_gpu.vendor_id)
        gpu_driver = state.selected_gpu.driver
    else:
        gpu_driver = None

    if not ids:
        return False, "No PCI devices selected for passthrough."

    unique_ids = list(dict.fromkeys(ids))  # deduplicate, preserve order
    ids_str = ",".join(unique_ids)

    lines = [
        "# BulwarkOS VFIO passthrough configuration",
        "# Generated by BulwarkOS OOBE wizard — do not edit manually",
        "# To reconfigure, run: bulwarkos-setup",
        "",
        f"options vfio-pci ids={ids_str}",
        "",
        "# Ensure vfio-pci binds before other drivers",
        "softdep vfio-pci pre: vfio",
    ]

    if gpu_driver and gpu_driver == "nvidia":
        lines += [
            "",
            "# Prevent Nvidia driver from claiming the GPU before vfio-pci",
            "softdep nvidia pre: vfio-pci",
            "softdep nvidia* pre: vfio-pci",
        ]
    elif gpu_driver and gpu_driver == "amdgpu":
        lines += [
            "",
            "softdep amdgpu pre: vfio-pci",
        ]

    content = "\n".join(lines) + "\n"
    try:
        if Path(MODPROBE_CONF).read_text() == content:
            return True, "VFIO modprobe config unchanged — skipped."
    except OSError:
        pass
    return _write_file_as_root(MODPROBE_CONF, content)


# ---------------------------------------------------------------------------
# Step 3 — dracut / initramfs
# ---------------------------------------------------------------------------

def step_initramfs(state: WizardState) -> tuple[bool, str]:
    """
    Writes /etc/dracut.conf.d/bulwarkos-vfio.conf and triggers an
    initramfs rebuild via rpm-ostree initramfs --enable.
    Skipped if dracut config is already correct and initramfs is enabled.
    """
    dracut_content = "\n".join([
        "# BulwarkOS VFIO initramfs configuration",
        "# Generated by BulwarkOS OOBE wizard",
        "",
        'add_drivers+=" vfio vfio_iommu_type1 vfio_pci "',
        'force_drivers+=" vfio-pci "',
        "",
    ])

    # Check if dracut config is already correct AND initramfs is already enabled.
    # rpm-ostree initramfs --enable is idempotent but slow (~60s) — skip if safe.
    dracut_already_correct = False
    try:
        if Path(DRACUT_CONF).read_text() == dracut_content:
            dracut_already_correct = True
    except OSError:
        pass

    initramfs_already_enabled = False
    if dracut_already_correct:
        ok_s, status = _run(["rpm-ostree", "status", "--json"], timeout=15)
        if ok_s and "initramfs-args" in status:
            initramfs_already_enabled = True

    if dracut_already_correct and initramfs_already_enabled:
        return True, "Initramfs config unchanged and already enabled — skipped."

    ok, msg = _write_file_as_root(DRACUT_CONF, dracut_content)
    if not ok:
        return False, f"Failed to write dracut config: {msg}"

    cmd = [
        "pkexec", "rpm-ostree", "initramfs",
        "--enable",
        "--arg=--add-drivers",
        "--arg=vfio vfio_pci vfio_iommu_type1",
    ]
    return _run(cmd, timeout=180)


# ---------------------------------------------------------------------------
# Step 4 — Configure /etc/libvirt/qemu.conf (user/group + libvirtd restart)
# ---------------------------------------------------------------------------

QEMU_CONF = "/etc/libvirt/qemu.conf"

# These are the two lines we need to set (commented out by default in stock
# qemu.conf, defaulting to "qemu"/"qemu"). We uncomment them and substitute
# the signed-in user's username so QEMU processes run under their UID/GID,
# which means disk images in /var/lib/bulwarkos/images/ are accessible and
# virsh/virt-manager launched as that user can fully manage running domains.
_QEMU_CONF_USER_RE  = r'^#?\s*user\s*=\s*"[^"]*"'
_QEMU_CONF_GROUP_RE = r'^#?\s*group\s*=\s*"[^"]*"'


def _get_current_username() -> str:
    """
    Returns the name of the user who launched the wizard.
    os.getlogin() can fail in some session types (e.g. via su/sudo),
    so we fall back through a chain of environment variables and pwd.
    """
    import pwd

    # SUDO_USER is set when the user used sudo — gives original username
    for env_var in ("SUDO_USER", "DBUS_SESSION_BUS_ADDRESS", "USER", "LOGNAME"):
        val = os.environ.get(env_var, "")
        if env_var == "SUDO_USER" and val:
            return val
        if env_var in ("USER", "LOGNAME") and val and val != "root":
            return val

    # Fall back to the real UID from the process credentials
    try:
        return pwd.getpwuid(os.getuid()).pw_name
    except KeyError:
        return "qemu"  # safe default — leaves behaviour unchanged


def step_configure_qemu(state: WizardState) -> tuple[bool, str]:
    """
    Edits /etc/libvirt/qemu.conf to set the QEMU process user and group to
    the signed-in user, then restarts libvirtd so the change takes effect
    before the network and VM definition steps run.

    Two lines are targeted (both commented out by default):
        #user = "qemu"    →  user = "<username>"
        #group = "qemu"   →  group = "<username>"

    The edit is done with a line-by-line regex substitution that:
      - handles the line whether it is currently commented out or not
      - preserves every other line in the file exactly as-is
      - writes back atomically via a temp file + pkexec mv

    A backup is written to /etc/libvirt/qemu.conf.bulwark.bak before any
    change is made, so the original can be restored if needed.
    """
    import re
    import tempfile

    username = _get_current_username()

    # --- Read current file ---------------------------------------------------
    # /etc/libvirt/qemu.conf is world-readable (644) on Fedora — read it
    # directly rather than via pkexec cat, which can trigger a polkit
    # authentication prompt and block indefinitely.
    try:
        content = Path(QEMU_CONF).read_text()
        read_ok = True
    except OSError as e:
        # File not readable directly — fall back to pkexec cat with longer timeout
        read_ok, content = _run(
            ["pkexec", "cat", QEMU_CONF],
            timeout=30,
        )
    if not read_ok:
        return False, f"Could not read {QEMU_CONF}: {content}"

    # --- Backup original (idempotent — only write if backup doesn't exist) ---
    backup_path = QEMU_CONF + ".bulwark.bak"
    _run(["pkexec", "bash", "-c",
          f'[ -f "{backup_path}" ] || cp "{QEMU_CONF}" "{backup_path}"'],
         timeout=10)

    # --- Early exit if already correctly configured -------------------------
    # Check if both lines already have the correct value (no-op re-run).
    user_line_ok  = f'user = "{username}"' in content.splitlines()
    group_line_ok = f'group = "{username}"' in content.splitlines()
    if user_line_ok and group_line_ok:
        # Already set — skip write but still ensure libvirtd is running
        _run(["pkexec", "systemctl", "restart", "libvirtd.service"], timeout=30)
        return True, f"QEMU already configured for '{username}'; libvirtd restarted."

    # --- Substitute user and group lines -------------------------------------
    # Each key is replaced exactly ONCE — the first matching line wins and
    # subsequent duplicates (from previous wizard runs) are removed.
    # This prevents lines accumulating on every re-run.
    new_lines: list[str] = []
    user_set  = False
    group_set = False

    for line in content.splitlines():
        if re.match(_QEMU_CONF_USER_RE, line):
            if not user_set:
                # First match — write the correct value
                new_lines.append(f'user = "{username}"')
                user_set = True
            # else: skip duplicate line entirely
        elif re.match(_QEMU_CONF_GROUP_RE, line):
            if not group_set:
                new_lines.append(f'group = "{username}"')
                group_set = True
            # else: skip duplicate line entirely
        else:
            new_lines.append(line)

    # If the directives weren't found at all (very unusual on a stock
    # Fedora qemu.conf), append them once at the end.
    if not user_set:
        new_lines.append(f'user = "{username}"')
    if not group_set:
        new_lines.append(f'group = "{username}"')

    new_content = "\n".join(new_lines) + "\n"

    # --- Write new content via temp file + pkexec mv -------------------------
    try:
        with tempfile.NamedTemporaryFile(
            mode="w", suffix=".conf", prefix="bulwark-qemu-", delete=False
        ) as tmp:
            tmp.write(new_content)
            tmp_path = tmp.name
    except OSError as e:
        return False, f"Failed to write temp file: {e}"

    ok, msg = _run(["pkexec", "mv", tmp_path, QEMU_CONF], timeout=10)
    if not ok:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        return False, f"Failed to install new qemu.conf: {msg}"

    ok, msg = _run(["pkexec", "chmod", "644", QEMU_CONF], timeout=10)
    if not ok:
        return False, f"qemu.conf written but chmod failed: {msg}"

    # --- Also ensure the user is in the libvirt group ------------------------
    # This lets virt-manager and virsh work without sudo for this user.
    _run(["pkexec", "usermod", "-aG", "libvirt", username], timeout=15)
    _run(["pkexec", "usermod", "-aG", "kvm",     username], timeout=15)

    # --- Restart libvirtd so the new user/group takes effect -----------------
    ok, msg = _run(
        ["pkexec", "systemctl", "restart", "libvirtd.service"],
        timeout=30,
    )
    if not ok:
        return False, (
            f"qemu.conf updated for user '{username}', but libvirtd "
            f"failed to restart: {msg}"
        )

    return True, f"QEMU configured to run as '{username}'; libvirtd restarted."


# ---------------------------------------------------------------------------
# Step 5 — libvirt network definitions (virsh net-define + net-start)
# ---------------------------------------------------------------------------

# Networks that must exist before any VM can start.
# Order matters: bulwark-internal must exist before sys-net is defined,
# bulwark-appvms must exist before sys-firewall and AppVMs are defined.
_NETWORKS = [
    "net-bulwark-internal",
    "net-bulwark-appvms",
]


def step_define_networks(state: WizardState) -> tuple[bool, str]:
    """
    Defines and auto-starts the two BulwarkOS libvirt bridge networks:

      bulwark-internal  — isolated /30 between sys-net and sys-firewall
      bulwark-appvms    — isolated /24 between sys-firewall and all AppVMs

    Both use forward mode='none' (no host NAT, no host participation).
    Marks both networks as autostart so they persist across host reboots.
    """
    template_dir = Path(NET_TEMPLATE_DIR)
    errors: list[str] = []

    for net_template in _NETWORKS:
        template_path = template_dir / f"{net_template}.xml"
        if not template_path.exists():
            errors.append(f"Network template not found: {net_template}.xml")
            continue

        # Extract the logical network name from the filename
        # e.g. "net-bulwark-internal" → "bulwark-internal"
        net_name = net_template.removeprefix("net-")

        # Check whether the network already exists (idempotent re-runs)
        check_ok, _ = _run(_VIRSH + ["net-info", net_name], timeout=10)
        if check_ok:
            # Already defined — ensure it's active and set to autostart
            _run(_VIRSH + ["net-start", net_name], timeout=15)
            _run(_VIRSH + ["net-autostart", net_name], timeout=10)
            continue

        # Define the network from the template XML
        ok, msg = _run(_VIRSH + ["net-define", str(template_path)], timeout=30)
        if not ok:
            errors.append(f"virsh net-define {net_name}: {msg}")
            continue

        # Start it immediately (so VMs defined in the next step can reference it)
        ok, msg = _run(_VIRSH + ["net-start", net_name], timeout=15)
        if not ok:
            errors.append(f"virsh net-start {net_name}: {msg}")
            continue

        # Mark as autostart so it comes up automatically after every host reboot
        ok, msg = _run(_VIRSH + ["net-autostart", net_name], timeout=10)
        if not ok:
            errors.append(f"virsh net-autostart {net_name}: {msg}")

    if errors:
        return False, "\n".join(errors)
    return True, f"Defined and started {len(_NETWORKS)} network(s)."

# ---------------------------------------------------------------------------
# Step 6 — Generate dedicated SSH keypair for infrastructure access
# ---------------------------------------------------------------------------
# Security model:
#   - A dedicated ED25519 keypair is generated specifically for BulwarkOS
#     infrastructure (sys-net, sys-firewall). It is NOT the user's existing
#     personal key — compromise of an AppVM cannot pivot to infra via a
#     shared key.
#   - Private key stored at ~/.config/bulwarkos/infra_key (mode 600)
#   - SSH client configured to use this key ONLY for infrastructure IPs
#     (10.10.0.x and 10.10.1.254) via a scoped ~/.ssh/config stanza
#   - sshd on sys-net/sys-firewall listens only on their bridge addresses,
#     never on any WAN/upstream interface

BULWARK_SSH_DIR   = Path.home() / ".config" / "bulwarkos"
BULWARK_INFRA_KEY = BULWARK_SSH_DIR / "infra_key"
BULWARK_INFRA_PUB = BULWARK_SSH_DIR / "infra_key.pub"
USER_SSH_CONFIG   = Path.home() / ".ssh" / "config"
_SSH_BLOCK_MARKER = "# BulwarkOS infrastructure access — managed by wizard"


def step_generate_ssh_key(state: WizardState) -> tuple[bool, str]:
    """
    Generates a dedicated ED25519 keypair for BulwarkOS infrastructure access
    and writes a scoped SSH client config. Idempotent: existing keypair reused.
    Stores the public key in state.ssh_public_key for cloud-init injection.
    """
    errors: list[str] = []

    try:
        BULWARK_SSH_DIR.mkdir(parents=True, exist_ok=True)
        BULWARK_SSH_DIR.chmod(0o700)
    except OSError as e:
        return False, f"Could not create {BULWARK_SSH_DIR}: {e}"

    # Reuse existing keypair if present (idempotent re-runs)
    if BULWARK_INFRA_KEY.exists() and BULWARK_INFRA_PUB.exists():
        state.ssh_public_key = BULWARK_INFRA_PUB.read_text().strip()
        return True, "Existing BulwarkOS infrastructure keypair reused."

    # Generate new keypair — no passphrase, key only usable from this host
    ok, msg = _run(
        ["ssh-keygen", "-t", "ed25519", "-f", str(BULWARK_INFRA_KEY),
         "-N", "", "-C", "bulwarkos-infra-access"],
        timeout=15,
    )
    if not ok:
        return False, f"ssh-keygen failed: {msg}"

    try:
        BULWARK_INFRA_KEY.chmod(0o600)
        BULWARK_INFRA_PUB.chmod(0o644)
        state.ssh_public_key = BULWARK_INFRA_PUB.read_text().strip()
    except OSError as e:
        return False, f"Could not read generated public key: {e}"

    # Append a scoped SSH client config stanza — restricts this key to infra IPs
    try:
        USER_SSH_CONFIG.parent.mkdir(parents=True, exist_ok=True)
        USER_SSH_CONFIG.parent.chmod(0o700)
        existing = USER_SSH_CONFIG.read_text() if USER_SSH_CONFIG.exists() else ""
        if _SSH_BLOCK_MARKER not in existing:
            block = (
                f"\n{_SSH_BLOCK_MARKER}\n"
                f"Host 10.10.0.1\n"
                f"    User bulwark\n"
                f"    IdentityFile {BULWARK_INFRA_KEY}\n"
                f"    IdentitiesOnly yes\n"
                f"    StrictHostKeyChecking no\n"
                f"    UserKnownHostsFile {BULWARK_SSH_DIR}/known_hosts\n"
                f"\nHost 10.10.0.2\n"
                f"    User bulwark\n"
                f"    IdentityFile {BULWARK_INFRA_KEY}\n"
                f"    IdentitiesOnly yes\n"
                f"    StrictHostKeyChecking no\n"
                f"    UserKnownHostsFile {BULWARK_SSH_DIR}/known_hosts\n"
                f"\nHost 10.10.1.254\n"
                f"    User bulwark\n"
                f"    IdentityFile {BULWARK_INFRA_KEY}\n"
                f"    IdentitiesOnly yes\n"
                f"    StrictHostKeyChecking no\n"
                f"    UserKnownHostsFile {BULWARK_SSH_DIR}/known_hosts\n"
                f"# End BulwarkOS infrastructure access\n"
            )
            with open(USER_SSH_CONFIG, "a") as f:
                f.write(block)
            USER_SSH_CONFIG.chmod(0o600)
    except OSError as e:
        errors.append(f"Could not update SSH client config: {e}")

    if errors:
        return True, f"Keypair generated (warnings: {'; '.join(errors)})"
    return True, f"Infrastructure keypair generated at {BULWARK_INFRA_KEY}."


# ---------------------------------------------------------------------------
# Step 7 — Provision disk images (download cloud images + cloud-init ISOs)
# ---------------------------------------------------------------------------

IMAGE_DIR      = "/var/lib/bulwarkos/images"
BASE_IMAGE_DIR = "/usr/share/bulwarkos/base-images"

# Both base images are shipped inside the BulwarkOS OCI image — no network
# download is required during OOBE.
# sys-net and sys-firewall use Rocky Linux 10 GenericCloud for full driver coverage.
# Fetched at OCI build time from dl.rockylinux.org — no GitHub upload needed.
_ROCKY_BASE        = f"{BASE_IMAGE_DIR}/rocky-base.qcow2"
# fedora-cloud-base.qcow2 replaced by fedora-gnome-base.qcow2.
_FEDORA_GNOME_BASE = f"{BASE_IMAGE_DIR}/fedora-gnome-base.qcow2"

# Tails ISO — downloaded on demand for the disposable VM.
# Tails is an amnesic live OS that routes all traffic through Tor.
# It boots directly from the ISO cdrom, no disk installation needed.
# Update this URL when a new Tails version is released.
TAILS_IMG_URL  = "https://download.tails.net/tails/stable/tails-amd64-7.7.1/tails-amd64-7.7.1.img"
TAILS_IMG_PATH = f"{IMAGE_DIR}/tails-latest.img"
# Minimum acceptable file size (bytes) — Tails images are ~1.5GB
TAILS_IMG_MIN_SIZE = 1_000_000_000


# Map each VM name to (image_type, disk_size_gb)
#   "rocky-shipped"  — thin qcow2 overlay on the shipped Rocky Linux 10 base
#   "fedora-gnome-shipped" — thin qcow2 overlay on the shipped Fedora GNOME base
#   "blank"               — empty qcow2, user installs OS themselves (gaming VM)
_VM_IMAGE_SPEC: dict[str, tuple[str, int]] = {
    "sys-net":      ("rocky-shipped",       16),
    "sys-firewall": ("rocky-shipped",        16),
    # GUI AppVMs — full GNOME Workstation desktop environment
    "personal":     ("fedora-gnome-shipped", 48),
    "work":         ("fedora-gnome-shipped", 60),
    "development":  ("fedora-gnome-shipped", 96),
    "media":        ("fedora-gnome-shipped", 48),
    # Banking: intentionally headless — Fedora Cloud Base only, no desktop
    # attack surface. Access via SSH or console only.
    "banking":      ("fedora-gnome-shipped", 24),
    # Disposable: Alpine clone — overlay is what actually runs each boot
    "disposable":   ("tails-live",            0),   # boots from ISO, no disk
    # Gaming VM: blank — user installs Windows 11 or similar manually
    "gaming-vm":    ("blank",                96),
}

# ---------------------------------------------------------------------------
# Cloud-init user-data for Alpine VMs
# ---------------------------------------------------------------------------
#
# Network layout:
#   bulwark-internal (/30 point-to-point):
#     sys-net       eth0  10.10.0.1/30   (WAN-side / uplink)
#     sys-firewall  eth0  10.10.0.2/30   (WAN-side, default GW = 10.10.0.1)
#
#   bulwark-appvms (/24 AppVM LAN):
#     sys-firewall  eth1  10.10.1.254/24  (LAN-side gateway for all AppVMs)
#
# Alpine Cloud uses predictable virtio NIC names: eth0, eth1 in XML order.
# sys-net  has one  interface  → eth0 = bulwark-internal
# sys-firewall has two interfaces → eth0 = bulwark-internal, eth1 = bulwark-appvms
#
# cloud-init network-config v1 is used (alpine-nocloud supports v1 natively).

# Path to wifi proxy data files — shipped in the wizard's data directory,
# baked into the OCI image, read at OOBE runtime by the wizard.
_WIFI_PROXY_DIR = Path(__file__).parent.parent / "data" / "wifi-proxy"


def _wifi_proxy_systemd_unit() -> str:
    """
    Returns the cloud-init write_files YAML block that installs
    bulwark-wifi-proxy and its systemd unit into sys-net (Rocky Linux).
    """
    try:
        proxy_src = (_WIFI_PROXY_DIR / "bulwark-wifi-proxy.py").read_text()
    except OSError as e:
        raise RuntimeError(
            f"Could not read wifi proxy from {_WIFI_PROXY_DIR}: {e}"
        ) from e

    systemd_unit = (
        "[Unit]\n"
        "Description=BulwarkOS WiFi proxy\n"
        "After=iwd.service network.target\n"
        "Requires=iwd.service\n"
        "\n"
        "[Service]\n"
        "Type=simple\n"
        "ExecStart=/usr/bin/python3 /usr/local/bin/bulwark-wifi-proxy\n"
        "Restart=on-failure\n"
        "RestartSec=5\n"
        "StandardOutput=journal\n"
        "StandardError=journal\n"
        "\n"
        "[Install]\n"
        "WantedBy=multi-user.target\n"
    )

    def _indent(text: str, spaces: int = 6) -> str:
        pad = " " * spaces
        return "\n".join(pad + line for line in text.splitlines())

    return (
        "  - path: /usr/local/bin/bulwark-wifi-proxy\n"
        '    permissions: "0755"\n'
        "    content: |\n"
        + _indent(proxy_src) + "\n\n"
        + "  - path: /etc/systemd/system/bulwark-wifi-proxy.service\n"
        '    permissions: "0644"\n'
        "    content: |\n"
        + _indent(systemd_unit) + "\n\n"
    )

def _make_rocky_userdata(vm_name: str, ssh_pub_key: str = "") -> tuple[str, str]:
    """
    Generate cloud-init user-data for Rocky Linux 10 sys-net and sys-firewall.

    Structure per Rocky Linux cloud-init docs (04_advanced_provisioning):
      - First YAML document: #cloud-config  (users, packages, write_files, runcmd)
      - Separator: ---
      - Second YAML document: network configuration (version 2)
      Both documents are returned as a single string for the user-data file.

    The network-config file passed to the NoCloud ISO is left empty — Rocky
    Linux 10 cloud-init reads the network block from the second YAML document
    in user-data when the NoCloud datasource is used.

    User account:
      - Creates 'bulwark' with passwordless sudo and the infra SSH key.
      - 'rocky' (the default cloud user) is left intact but not used.
      - SSH as: ssh -i ~/.config/bulwarkos/infra_key bulwark@<ip>
    """

    # ── User block ────────────────────────────────────────────────────────────
    # Always create the bulwark user. Inject the infra key when provided.
    # ssh_authorized_keys items must be indented 6 spaces under the
    # users list entry (4 spaces for the key, 2 more for list item indent)
    if ssh_pub_key.strip():
        key_line = "      - " + ssh_pub_key.strip() + "\n"
        ssh_keys_block = "    ssh_authorized_keys:\n" + key_line
    else:
        ssh_keys_block = ""

    user_block = (
        "users:\n"
        "  - name: bulwark\n"
        "    gecos: BulwarkOS Infrastructure\n"
        "    groups: [wheel]\n"
        "    shell: /bin/bash\n"
        "    sudo: ALL=(ALL) NOPASSWD:ALL\n"
        "    lock_passwd: true\n"
        + ssh_keys_block
        + "\n"
    )

    # ── Per-VM config ─────────────────────────────────────────────────────────
    if vm_name == "sys-net":
        listen_addr   = "10.10.0.1"
        dnsmasq_pkg   = ""
        dnsmasq_runcmd= ""
        wifi_write_files = _wifi_proxy_systemd_unit()
        wifi_packages    = "  - iwd\n  - python3\n  - python3-dbus\n"
        wifi_runcmd      = (
            "  - systemctl enable --now iwd\n"
            "  - systemctl enable --now bulwark-wifi-proxy\n"
        )
        extra_packages = (
            "  - iwl7260-firmware\n"
            "  - iwlax210-firmware\n"
            "  - linux-firmware\n"
        )
        extra_runcmd = (
            "  - modprobe igc || true\n"
            "  - modprobe iwlwifi || true\n"
        )
        # nftables: match traffic by IP subnet, not interface name,
        # since passthrough NIC names are not predictable.
        nft_conf = (
            "#!/usr/sbin/nft -f\n"
            "# sys-net: internal link to sys-firewall = 10.10.0.x/30\n"
            "#          WAN NICs = everything else (passthrough, names vary)\n"
            "flush ruleset\n\n"
            "table inet filter {\n"
            "  chain input {\n"
            "    type filter hook input priority 0; policy drop;\n"
            "    ct state established,related accept\n"
            "    iifname \"lo\" accept\n"
            "    ip saddr 10.10.0.0/30 tcp dport 22 accept\n"
            "    ip saddr 10.10.0.0/30 icmp type echo-request accept\n"
            "    drop\n"
            "  }\n"
            "  chain forward {\n"
            "    type filter hook forward priority 0; policy drop;\n"
            "    ct state established,related accept\n"
            "    ip saddr 10.10.0.0/30 accept\n"
            "    drop\n"
            "  }\n"
            "  chain output {\n"
            "    type filter hook output priority 0; policy accept;\n"
            "  }\n"
            "}\n\n"
            "table ip nat {\n"
            "  chain postrouting {\n"
            "    type nat hook postrouting priority 100;\n"
            "    ip daddr != 10.10.0.0/30 masquerade\n"
            "  }\n"
            "}\n"
        )
        # Network: eth0 = virtio link to sys-firewall, 10.10.0.1/30, no gateway
        # Passthrough NICs are managed by iwd/NM directly (DHCP from ISP)
        net_doc = (
            "network:\n"
            "  version: 2\n"
            "  ethernets:\n"
            "    eth0:\n"
            "      dhcp4: false\n"
            "      addresses:\n"
            "        - 10.10.0.1/30\n"
        )

    elif vm_name == "sys-firewall":
        listen_addr   = "10.10.0.2"
        dnsmasq_pkg   = "  - dnsmasq\n"
        dnsmasq_runcmd= "  - systemctl enable --now dnsmasq\n"
        wifi_write_files = ""
        wifi_packages    = ""
        wifi_runcmd      = ""
        extra_packages   = ""
        extra_runcmd     = ""
        nft_conf = (
            "#!/usr/sbin/nft -f\n"
            "# sys-firewall: eth0 = WAN (10.10.0.x/30), eth1 = AppVM LAN (10.10.1.x/24)\n"
            "flush ruleset\n\n"
            "table inet filter {\n"
            "  chain input {\n"
            "    type filter hook input priority 0; policy drop;\n"
            "    ct state established,related accept\n"
            "    iifname \"lo\" accept\n"
            "    iifname \"eth0\" tcp dport 22 accept\n"
            "    iifname \"eth0\" icmp type echo-request accept\n"
            "    iifname \"eth1\" tcp dport 22 accept\n"
            "    iifname \"eth1\" icmp type echo-request accept\n"
            "    iifname \"eth1\" udp dport 53 accept\n"
            "    iifname \"eth1\" tcp dport 53 accept\n"
            "    iifname \"eth1\" udp dport 67 accept\n"
            "    drop\n"
            "  }\n"
            "  chain forward {\n"
            "    type filter hook forward priority 0; policy drop;\n"
            "    ct state established,related accept\n"
            "    iifname \"eth1\" oifname \"eth0\" accept\n"
            "    drop\n"
            "  }\n"
            "  chain output {\n"
            "    type filter hook output priority 0; policy accept;\n"
            "  }\n"
            "}\n\n"
            "table ip nat {\n"
            "  chain postrouting {\n"
            "    type nat hook postrouting priority 100;\n"
            "    oifname \"eth0\" masquerade\n"
            "  }\n"
            "}\n"
        )
        # Network: eth0 = link to sys-net (gateway = sys-net's IP)
        #          eth1 = AppVM LAN (no gateway, local only)
        # routes: used instead of deprecated gateway4
        net_doc = (
            "network:\n"
            "  version: 2\n"
            "  ethernets:\n"
            "    eth0:\n"
            "      dhcp4: false\n"
            "      addresses:\n"
            "        - 10.10.0.2/30\n"
            "      routes:\n"
            "        - to: default\n"
            "          via: 10.10.0.1\n"
            "      nameservers:\n"
            "        addresses: [1.1.1.1, 9.9.9.9]\n"
            "    eth1:\n"
            "      dhcp4: false\n"
            "      addresses:\n"
            "        - 10.10.1.254/24\n"
        )

    else:
        listen_addr      = "0.0.0.0"
        dnsmasq_pkg      = ""
        dnsmasq_runcmd   = ""
        wifi_write_files = ""
        wifi_packages    = ""
        wifi_runcmd      = ""
        extra_packages   = ""
        extra_runcmd     = ""
        nft_conf         = ""
        net_doc          = (
            "network:\n"
            "  version: 2\n"
            "  ethernets:\n"
            "    eth0:\n"
            "      dhcp4: true\n"
        )

    # ── Indent helper for write_files content blocks ──────────────────────────
    def _ind(text: str, n: int = 6) -> str:
        pad = " " * n
        return "\n".join(pad + l for l in text.splitlines())

    # ── dnsmasq config for sys-firewall ───────────────────────────────────────
    dnsmasq_write_files = ""
    if vm_name == "sys-firewall":
        dnsmasq_conf = (
            "interface=eth1\n"
            "bind-interfaces\n"
            "dhcp-range=10.10.1.10,10.10.1.200,12h\n"
            "dhcp-option=3,10.10.1.254\n"
            "dhcp-option=6,10.10.1.254\n"
            "server=1.1.1.1\n"
            "server=9.9.9.9\n"
            "no-resolv\n"
        )
        dnsmasq_write_files = (
            "  - path: /etc/dnsmasq.d/bulwark-appvms.conf\n"
            "    permissions: \"0644\"\n"
            "    content: |\n"
            + _ind(dnsmasq_conf) + "\n\n"
        )

    # ── nftables write_files block ────────────────────────────────────────────
    nft_write_files = ""
    if nft_conf:
        nft_write_files = (
            "  - path: /etc/nftables.conf\n"
            "    permissions: \"0640\"\n"
            "    content: |\n"
            + _ind(nft_conf) + "\n\n"
        )

    # ── sshd drop-in ─────────────────────────────────────────────────────────
    # Rocky 10 sshd_config includes /etc/ssh/sshd_config.d/*.conf by default
    sshd_conf = (
        "Port 22\n"
        "ListenAddress " + listen_addr + "\n"
        "PermitRootLogin no\n"
        "PubkeyAuthentication yes\n"
        "AuthorizedKeysFile .ssh/authorized_keys\n"
        "PasswordAuthentication no\n"
        "PermitEmptyPasswords no\n"
        "ChallengeResponseAuthentication no\n"
    )
    if vm_name == "sys-firewall":
        # Also listen on the AppVM LAN interface
        sshd_conf = (
            "Port 22\n"
            "ListenAddress 10.10.0.2\n"
            "ListenAddress 10.10.1.254\n"
            "PermitRootLogin no\n"
            "PubkeyAuthentication yes\n"
            "AuthorizedKeysFile .ssh/authorized_keys\n"
            "PasswordAuthentication no\n"
            "PermitEmptyPasswords no\n"
            "ChallengeResponseAuthentication no\n"
        )

    sshd_write_file = (
        "  - path: /etc/ssh/sshd_config.d/99-bulwark.conf\n"
        "    permissions: \"0600\"\n"
        "    content: |\n"
        + _ind(sshd_conf) + "\n\n"
    )

    sysctl_write_file = (
        "  - path: /etc/sysctl.d/99-bulwark-forward.conf\n"
        "    permissions: \"0644\"\n"
        "    content: |\n"
        "      net.ipv4.ip_forward = 1\n"
        "      net.ipv6.conf.all.forwarding = 1\n\n"
    )

    # ── Assemble user-data (first YAML document) ──────────────────────────────
    userdata = (
        "#cloud-config\n"
        "hostname: " + vm_name + "\n\n"
        + user_block
        + "packages:\n"
        "  - nftables\n"
        "  - openssh-server\n"
        + dnsmasq_pkg
        + extra_packages
        + wifi_packages
        + "\n"
        "write_files:\n"
        + sysctl_write_file
        + nft_write_files
        + sshd_write_file
        + dnsmasq_write_files
        + wifi_write_files
        + "runcmd:\n"
        "  - sysctl -p /etc/sysctl.d/99-bulwark-forward.conf\n"
        "  - systemctl enable --now nftables\n"
        + ("  - nft -f /etc/nftables.conf\n" if nft_conf else "")
        + "  - systemctl enable --now sshd\n"
        + dnsmasq_runcmd
        + extra_runcmd
        + wifi_runcmd
        # Reload NM so the network-config document's settings take effect
        + "  - nmcli connection reload\n"
        # ── Second YAML document: network configuration ──────────────────────
        # Separated by --- per Rocky Linux cloud-init docs.
        # cloud-init reads both documents from user-data when using NoCloud.
        + "---\n"
        + net_doc
    )

    # network-config file in the ISO: left empty because Rocky reads
    # the network block from the second document in user-data.
    return userdata, ""



# cloud-init user-data for Fedora AppVMs.
# AppVMs receive DHCP from sys-firewall's dnsmasq (10.10.1.0/24).
# A static fallback route ensures connectivity even before dnsmasq is running.
_FEDORA_USERDATA = """#cloud-config
hostname: {hostname}
user: bulwark
password: changeme
chpasswd:
  expire: true
ssh_pwauth: false
packages:
  - firewalld
  - bash-completion
network:
  version: 1
  config:
    - type: physical
      name: eth0
      subnets:
        - type: dhcp
          routes:
            - network: 0.0.0.0
              prefix: 0
              gateway: 10.10.1.254
runcmd:
  - systemctl enable --now firewalld
"""


# cloud-init user-data for Fedora GNOME AppVMs.
# The fedora-gnome-base.qcow2 already has GNOME installed; cloud-init sets up
# the user account, enables auto-login, and configures the system.
_FEDORA_GNOME_USERDATA = """#cloud-config
hostname: {hostname}
users:
  - name: bulwark
    gecos: BulwarkOS User
    groups: [wheel, libvirt, kvm]
    shell: /bin/bash
    lock_passwd: false
    passwd: $6$rounds=4096$bulwark$placeholder
    sudo: ALL=(ALL) NOPASSWD:ALL

chpasswd:
  list:
    - bulwark:changeme
  expire: true

ssh_pwauth: false

packages:
  - firewalld
  - bash-completion
  - gnome-tweaks

runcmd:
  # Enable firewalld
  - systemctl enable --now firewalld
  # Enable GDM auto-login for the bulwark user on first boot
  - mkdir -p /etc/gdm
  - |
    cat > /etc/gdm/custom.conf << 'EOF'
    [daemon]
    AutomaticLoginEnable=true
    AutomaticLogin=bulwark
    EOF
  # Ensure Wayland is used (not X11)
  - sed -i 's/^#WaylandEnable=false/WaylandEnable=true/' /etc/gdm/custom.conf || true
  # Set GNOME as default session
  - ln -sf /usr/share/wayland-sessions/gnome.desktop /etc/alternatives/desktop-session || true
"""


def _make_cloud_init_iso(
    vm_name: str, image_type: str, dest_dir: Path,
    ssh_pub_key: str = ""
) -> tuple[bool, str, str]:
    """
    Generates a NoCloud cloud-init seed ISO (volume label: cidata) in dest_dir.
    Returns (success, message, iso_path_or_empty).
    Tries genisoimage -> mkisofs -> xorriso in order.

    image_type: "rocky-shipped"        → calls _make_rocky_userdata(vm_name)
                "fedora-gnome-shipped" → uses _FEDORA_GNOME_USERDATA template
    """
    import tempfile, shutil

    network_config: str | None = None

    if image_type == "rocky-shipped":
        # Returns (userdata_str, network_config_str) tuple
        userdata, network_config = _make_rocky_userdata(vm_name, ssh_pub_key)
    else:
        # All Fedora AppVMs use the GNOME base image and userdata
        userdata = _FEDORA_GNOME_USERDATA.format(hostname=vm_name)
        if ssh_pub_key.strip():
            userdata = userdata.replace(
                "ssh_pwauth: false",
                f"ssh_authorized_keys:\n  - {ssh_pub_key.strip()}\n\nssh_pwauth: false",
            )
        # Fedora AppVMs get DHCP — static gateway via separate network-config
        network_config = (
            "version: 1\n"
            "config:\n"
            "  - type: physical\n"
            "    name: eth0\n"
            "    subnets:\n"
            "      - type: dhcp\n"
            "        routes:\n"
            "          - network: 0.0.0.0\n"
            "            prefix: 0\n"
            "            gateway: 10.10.1.254\n"
        )

    # Use a unique instance-id every time the wizard generates an ISO.
    # Cloud-init caches by instance-id — if the id matches the previous
    # boot, it skips all modules (packages, runcmd, write_files, etc.).
    # A timestamp suffix guarantees cloud-init treats each wizard run as
    # a fresh instance, ensuring packages are always installed.
    import time as _time
    _iid = f"{vm_name}-{int(_time.time())}"
    metadata = f"instance-id: {_iid}\nlocal-hostname: {vm_name}\n"
    iso_path = str(dest_dir / f"{vm_name}-cloud-init.iso")

    try:
        work_dir = Path(tempfile.mkdtemp(prefix=f"bulwark-ci-{vm_name}-"))
        (work_dir / "user-data").write_text(userdata)
        (work_dir / "meta-data").write_text(metadata)
        # Write network-config as a separate file — the NoCloud datasource reads
        # this directly for network configuration on all cloud-init versions.
        if network_config:
            (work_dir / "network-config").write_text(network_config)
    except OSError as e:
        return False, f"Failed to write cloud-init seed files: {e}", ""

    for tool in ("genisoimage", "mkisofs", "xorriso"):
        cmd = (
            ["xorriso", "-as", "mkisofs",
             "-output", iso_path, "-volid", "cidata", "-joliet", "-rock",
             str(work_dir)]
            if tool == "xorriso"
            else [tool, "-output", iso_path, "-volid", "cidata",
                  "-joliet", "-rock", str(work_dir)]
        )
        ok, msg = _run(cmd, timeout=30)
        if ok:
            shutil.rmtree(work_dir, ignore_errors=True)
            return True, f"cloud-init ISO created for {vm_name}", iso_path

    shutil.rmtree(work_dir, ignore_errors=True)
    return False, "genisoimage/mkisofs/xorriso not found — install genisoimage", ""


def _qemu_img_create_overlay(
    base_path: str,
    base_fmt: str,
    dest_path: str,
    size_gb: int,
    timeout: int = 60,
) -> tuple[bool, str]:
    """
    Creates a thin qcow2 overlay on top of base_path using the
    '-o backing_file=...,backing_fmt=...' form so that the resulting
    qcow2 is self-contained and bootable without any separate cdrom
    device in the libvirt domain XML.

    Equivalent shell command:
        qemu-img create -f qcow2 \
            -o backing_file=<base>,backing_fmt=<fmt> \
            <dest> <size>G
    """
    return _run(
        [
            "qemu-img", "create",
            "-f", "qcow2",
            "-o", f"backing_file={base_path},backing_fmt={base_fmt}",
            dest_path,
            f"{size_gb}G",
        ],
        timeout=timeout,
    )


def step_provision_images(state: WizardState) -> tuple[bool, str]:
    """
    Provisions per-VM qcow2 disk images into IMAGE_DIR.

    All base images are shipped inside the BulwarkOS OCI image — no network
    activity is required during this step.

    Rocky Linux VMs (sys-net, sys-firewall):
      Creates a qcow2 overlay on the shipped Rocky Linux 10 GenericCloud base.
      A cloud-init seed ISO is generated so the VM configures itself on first boot.

    Fedora AppVMs (personal, work, banking, development, media):
      Same approach using the shipped Fedora Cloud Base as the backing layer.

    Gaming VM:
      Blank qcow2 only — user installs Windows 11 manually post-setup.

    Disposable VM:
      After the overlay is created it is split: the overlay is renamed to
      disposable-base.qcow2 and a second writable overlay is created on
      top of it. bulwarkos-disposable-reset.service recreates that outer
      overlay on every shutdown to guarantee a clean slate each boot.
    """
    import tempfile, shutil

    errors: list[str] = []

    # 1. Verify shipped base images exist — they are fetched at OCI build time
    #    from the GitHub Release. If missing, the OCI build failed to download
    #    them (wrong URL, missing release asset, or network failure during build).
    missing = []
    for label, path in (
        ("Rocky Linux",   _ROCKY_BASE),
        ("Fedora GNOME",  _FEDORA_GNOME_BASE),
    ):
        if not Path(path).exists():
            missing.append(f"{label} ({path})")
    if missing:
        return False, (
            f"Base image(s) not found: {', '.join(missing)}. "
            f"These are downloaded at OCI build time from the GitHub Release. "
            f"Check that the release assets exist at the URL configured in "
            f"bluebuild/recipe.yml and rebuild the BulwarkOS image."
        )

    # 2. Create IMAGE_DIR as root
    ok, msg = _run(["pkexec", "mkdir", "-p", IMAGE_DIR], timeout=10)
    if not ok:
        return False, f"Could not create image directory {IMAGE_DIR}: {msg}"

    # 3. Staging area — writable by the wizard user
    stage_dir = Path(tempfile.mkdtemp(prefix="bulwark-images-"))

    # 4. Build the list of VMs to provision
    all_vms = ["sys-net", "sys-firewall"] + list(state.selected_appvms)
    if state.gpu_passthrough and state.selected_gpu:
        all_vms.append("gaming-vm")

    # 5. Create per-VM disk images
    #
    # Architecture:
    #   Alpine/Fedora VMs:
    #     - {vm}.qcow2          thin overlay on shipped base image (boots the OS)
    #     - {vm}-cloud-init.iso cidata seed ISO attached as a separate cdrom device
    #                           cloud-init finds it by scanning for volume label "cidata"
    #                           The ISO is NOT part of the disk backing chain.
    #   Blank VMs (gaming):
    #     - {vm}.qcow2          empty qcow2, user installs OS manually
    #
    for vm_name in all_vms:
        image_type, size_gb = _VM_IMAGE_SPEC.get(vm_name, ("blank", 20))
        dest_image = str(stage_dir / f"{vm_name}.qcow2")

        # Skip if this VM's disk image already exists in IMAGE_DIR.
        # On re-runs (e.g. testing or feature updates) we do not want to
        # overwrite a disk that has already been configured by cloud-init.
        # The cloud-init ISO is also skipped — cloud-init only runs once.
        final_image_path = Path(f"{IMAGE_DIR}/{vm_name}.qcow2")
        if final_image_path.exists():
            continue

        if image_type in ("rocky-shipped", "fedora-gnome-shipped"):
            if image_type == "rocky-shipped":
                base_path = _ROCKY_BASE
            else:
                base_path = _FEDORA_GNOME_BASE

            # 5a. Create the VM disk as a thin qcow2 overlay on the base image.
            #     The base image is the pre-installed Alpine/Fedora Cloud qcow2 —
            #     it boots directly without any installer step.
            ok, msg = _qemu_img_create_overlay(
                base_path=base_path,
                base_fmt="qcow2",
                dest_path=dest_image,
                size_gb=size_gb,
                timeout=60,
            )
            if not ok:
                errors.append(f"qemu-img create {vm_name}: {msg}")
                continue

            # 5b. Generate the cloud-init seed ISO and install it into IMAGE_DIR.
            #     This is attached as a separate cdrom device in the domain XML.
            #     cloud-init scans block devices for volume label "cidata" and
            #     reads user-data/meta-data from it on first boot — it does NOT
            #     look in the primary disk's backing chain.
            ci_ok, ci_msg, iso_stage = _make_cloud_init_iso(
                vm_name, image_type, stage_dir,
                ssh_pub_key=state.ssh_public_key,
            )
            if not ci_ok:
                errors.append(f"cloud-init ISO {vm_name} (non-fatal): {ci_msg}")
                # VM will still boot from the base image; cloud-init won't configure it
            else:
                final_iso = f"{IMAGE_DIR}/{vm_name}-cloud-init.iso"
                ok, msg = _run(
                    ["pkexec", "mv", iso_stage, final_iso], timeout=10
                )
                if not ok:
                    errors.append(f"Failed to install cloud-init ISO {vm_name}: {msg}")
                else:
                    _run(["pkexec", "chmod", "660", final_iso], timeout=10)

        elif image_type == "tails-live":
            # Tails boots from a raw .img file — no qcow2 disk needed.
            # Download to a user-writable temp path first, then move as root.
            # This avoids running curl under pkexec/root.
            if not Path(TAILS_IMG_PATH).exists():
                import tempfile as _tf
                with _tf.NamedTemporaryFile(
                    dir="/tmp", suffix=".img",
                    prefix="tails-download-", delete=False
                ) as _tmp:
                    tmp_img = _tmp.name

                ok, msg = _run(
                    ["curl", "-fL",
                     "--retry", "3", "--retry-delay", "5",
                     "--connect-timeout", "30",
                     "-#",  # progress bar (visible in wizard log)
                     "-o", tmp_img,
                     TAILS_IMG_URL],
                    timeout=1800,  # 30 min — image is ~1.5GB
                )
                if not ok:
                    import os as _os
                    _os.unlink(tmp_img)
                    errors.append(f"Tails download failed: {msg}")
                    continue

                # Sanity check — reject obviously truncated downloads
                import os as _os
                actual_size = _os.path.getsize(tmp_img)
                if actual_size < TAILS_IMG_MIN_SIZE:
                    _os.unlink(tmp_img)
                    errors.append(
                        f"Tails image too small ({actual_size} bytes) — "
                        f"download may be truncated. Expected >{TAILS_IMG_MIN_SIZE} bytes."
                    )
                    continue

                # Move into IMAGE_DIR as root and set permissions
                ok, msg = _run(
                    ["pkexec", "mv", tmp_img, TAILS_IMG_PATH],
                    timeout=30,
                )
                if not ok:
                    errors.append(f"Failed to install Tails image: {msg}")
                    continue
                _run(["pkexec", "chmod", "644", TAILS_IMG_PATH], timeout=10)

            # Create a small scratch disk for Tails Persistent Storage
            scratch = f"{IMAGE_DIR}/disposable-scratch.qcow2"
            if not Path(scratch).exists():
                ok, msg = _run(
                    ["pkexec", "qemu-img", "create", "-f", "qcow2",
                     scratch, "8G"],
                    timeout=30,
                )
                if not ok:
                    errors.append(f"Failed to create Tails scratch disk: {msg}")
                _run(["pkexec", "chmod", "660", scratch], timeout=10)


        elif image_type == "blank":
            ok, msg = _run(
                ["qemu-img", "create", "-f", "qcow2", dest_image, f"{size_gb}G"],
                timeout=30,
            )
            if not ok:
                errors.append(f"qemu-img create (blank) {vm_name}: {msg}")
                continue

        # 6. Move the VM disk qcow2 into IMAGE_DIR as root.
        final_image = f"{IMAGE_DIR}/{vm_name}.qcow2"
        ok, msg = _run(["pkexec", "mv", dest_image, final_image], timeout=30)
        if not ok:
            errors.append(f"Failed to install image {vm_name}: {msg}")
            continue
        _run(["pkexec", "chmod", "660", final_image], timeout=10)

    # 7. Disposable VM — split into pristine base + writable overlay
    if "disposable" in all_vms and not any("disposable" in e for e in errors):
        base_img    = f"{IMAGE_DIR}/disposable-base.qcow2"
        overlay_img = f"{IMAGE_DIR}/disposable-overlay.qcow2"
        clone_img   = f"{IMAGE_DIR}/disposable.qcow2"

        ok, msg = _run(["pkexec", "mv", clone_img, base_img], timeout=10)
        if ok:
            # Create the overlay in a temp location, then move it into place
            overlay_stage = str(stage_dir / "disposable-overlay.qcow2")
            ok, msg = _qemu_img_create_overlay(
                base_path=base_img,
                base_fmt="qcow2",
                dest_path=overlay_stage,
                size_gb=10,
                timeout=30,
            )
            if ok:
                mv_ok, mv_msg = _run(
                    ["pkexec", "mv", overlay_stage, overlay_img], timeout=15
                )
                if mv_ok:
                    _run(["pkexec", "chmod", "660", overlay_img], timeout=10)
                else:
                    errors.append(f"disposable overlay install: {mv_msg}")
            else:
                errors.append(f"disposable overlay create: {msg}")
        else:
            errors.append(f"disposable base rename: {msg}")

    shutil.rmtree(stage_dir, ignore_errors=True)

    if errors:
        return False, "\n".join(errors)
    return True, f"Provisioned disk images for {len(all_vms)} VM(s)."

# ---------------------------------------------------------------------------
# Step 8 — VM domain definitions (virsh define)
# ---------------------------------------------------------------------------

def _render_template(template_path: Path, replacements: dict[str, str]) -> str:
    """Simple token substitution for libvirt XML templates.
    Raises ValueError if a provided key has no matching {{KEY}} in the template.
    """
    content = template_path.read_text()
    for key, value in replacements.items():
        placeholder = f"{{{{{key}}}}}"
        if placeholder not in content:
            if value:
                # Non-empty value with no matching placeholder — real bug
                raise ValueError(
                    f"Template {template_path.name} has no placeholder {placeholder!r}. "
                    f"The {key} substitution will be silently dropped."
                )
            # Empty value + no placeholder = no-op, skip silently
            continue
        content = content.replace(placeholder, value)
    return content


def step_define_vms(state: WizardState) -> tuple[bool, str]:
    """
    Calls virsh define for sys-net, sys-firewall, and each selected AppVM.
    Template XML files live in /usr/share/bulwarkos/vm-templates/.
    """
    template_dir = Path(VM_TEMPLATE_DIR)
    errors: list[str] = []

    # Build NIC passthrough XML fragment
    nic_hostdevs = ""
    for nic in state.selected_nics:
        addr = nic.pci_address  # e.g. "0000:05:00.0"
        parts = addr.split(":")
        domain = parts[0]
        bus_func = parts[2].split(".")
        bus = parts[1]
        slot = bus_func[0]
        function = bus_func[1]
        nic_hostdevs += f"""
    <hostdev mode='subsystem' type='pci' managed='yes'>
      <source>
        <address domain='0x{domain}' bus='0x{bus}' slot='0x{slot}' function='0x{function}'/>
      </source>
    </hostdev>"""

    # GPU passthrough XML fragment
    # Build GPU hostdev XML for gaming-vm.
    # For NVIDIA GPUs, also pass through companion devices in the same
    # IOMMU group (audio controller, USB controller) — NVIDIA GPUs are
    # typically in a group with their own audio device (function 1) and
    # sometimes a USB controller (function 2/3). All must be passed together.
    gpu_hostdevs = ""
    if state.gpu_passthrough and state.selected_gpu:
        def _pci_hostdev(pci_addr: str) -> str:
            parts = pci_addr.split(":")
            domain  = parts[0]
            bus     = parts[1]
            sf      = parts[2].split(".")
            slot    = sf[0]
            func    = sf[1]
            return (
                "\n    <hostdev mode='subsystem' type='pci' managed='yes'>\n"
                "      <source>\n"
                f"        <address domain='0x{domain}' bus='0x{bus}' slot='0x{slot}' function='0x{func}'/>\n"
                "      </source>\n"
                "    </hostdev>"
            )

        gpu_addr = state.selected_gpu.pci_address
        gpu_hostdevs += _pci_hostdev(gpu_addr)

        # Enumerate IOMMU group for companion devices.
        # NVIDIA GPUs ship with audio (fn 1) and sometimes USB (fn 2).
        # We detect them by looking at sibling functions on the same slot.
        import glob as _glob
        try:
            # Normalise address to 0000:BB:SS.F format
            addr_parts = gpu_addr.split(":")
            if len(addr_parts) == 2:
                pci_full = "0000:" + gpu_addr
            else:
                pci_full = gpu_addr
            iommu_path = "/sys/bus/pci/devices/" + pci_full
            group_path = iommu_path + "/iommu_group/devices"
            siblings = sorted(_glob.glob(group_path + "/*"))
            for sib_path in siblings:
                try:
                    sib_name = sib_path.split("/")[-1]  # e.g. 0000:01:00.1
                    # Strip domain prefix to get BB:SS.F
                    sib_addr = sib_name.split(":", 1)[-1] if ":" in sib_name else sib_name
                    # Skip the GPU itself
                    if sib_addr == gpu_addr or sib_name == pci_full:
                        continue
                    # Only include devices on the same bus:slot (different function)
                    gpu_busslot = gpu_addr.rsplit(".", 1)[0] if "." in gpu_addr else gpu_addr
                    sib_busslot = sib_addr.rsplit(".", 1)[0] if "." in sib_addr else sib_addr
                    if sib_busslot == gpu_busslot:
                        gpu_hostdevs += _pci_hostdev(sib_addr)
                except (IndexError, ValueError):
                    continue
        except OSError:
            pass

    # VMs to define: always sys-net + sys-firewall, then selected AppVMs
    vm_configs = [
        ("sys-net", {}),
        ("sys-firewall", {}),
    ]
    for appvm in state.selected_appvms:
        vm_configs.append((appvm, {}))

    import tempfile

    for vm_name, replacements in vm_configs:
        template_path = template_dir / f"{vm_name}.xml"
        if not template_path.exists():
            errors.append(f"Template not found: {vm_name}.xml")
            continue

        try:
            xml = _render_template(template_path, replacements)
        except (OSError, ValueError) as e:
            errors.append(f"Failed to render template {vm_name}.xml: {e}")
            continue

        # Inject NIC passthrough hostdev blocks for sys-net.
        # Inserted directly before </devices> — no placeholder in the template
        # so the XML file is always valid on its own.
        if vm_name == "sys-net" and nic_hostdevs and "</devices>" in xml:
            xml = xml.replace("</devices>",
                              nic_hostdevs + "\n  </devices>", 1)

        # Inject GPU + companion device hostdev blocks for gaming-vm.
        # Same pattern as NIC injection — no placeholder needed in the template.
        if vm_name == "gaming-vm" and gpu_hostdevs and "</devices>" in xml:
            xml = xml.replace("</devices>",
                              gpu_hostdevs + "\n  </devices>", 1)

        with tempfile.NamedTemporaryFile(
            mode="w", suffix=".xml", prefix=f"bulwark-{vm_name}-", delete=False
        ) as tmp:
            tmp.write(xml)
            tmp_path = tmp.name

        ok, msg = _run(_VIRSH + ["define", tmp_path])
        os.unlink(tmp_path)
        if not ok:
            errors.append(f"virsh define {vm_name}: {msg}")
            continue

        # Enable autostart for the infrastructure VMs — they must start before
        # any AppVM sessions and before the user logs in.
        if vm_name in ("sys-net", "sys-firewall"):
            ok_a, msg_a = _run(_VIRSH + ["autostart", vm_name])
            if not ok_a:
                errors.append(f"virsh autostart {vm_name}: {msg_a}")

    if errors:
        return False, "\n".join(errors)
    return True, f"Defined {len(vm_configs)} VM(s) successfully."

# ---------------------------------------------------------------------------
# Step 9 — Looking Glass Client
# ---------------------------------------------------------------------------
# Only runs when:
#   state.gpu_passthrough is True  (a GPU was selected)
#   state.install_looking_glass is True  (user opted in on the GPU screen)
#
# Architecture on an immutable BulwarkOS host:
#   - The KVMFR kernel module is preinstalled via hikariknight/looking-glass-kvmfr
#     which ships a pre-built kmod RPM for the current Fedora kernel.
#   - The Looking Glass Client is built from source within Toolbox.
#   - The Looking Glass Server (VM / Guest Application) does not run on
#     the host and is installed inside the Windows gaming VM by the user.
#   - /usr/local/ persists across rpm-ostree deployments (it is a bind-mount
#     from /var/usrlocal), so installed binaries survive system upgrades.

_LG_TOOLBOX_NAME   = "bulwarkos-lg-build"
_LG_SOURCE_URL     = "https://looking-glass.io/artifact/stable/source"
_LG_SOURCE_TAR     = "/tmp/looking-glass-src.tar.gz"
_LG_BUILD_DIR      = "/tmp/looking-glass-build"
_LG_CLIENT_DEST    = "/usr/local/bin/looking-glass-client"
_LG_SHMEM_SIZE_MB  = 128  # covers up to 4K; 256 for 8K

# Build deps installed inside the toolbox container
_LG_BUILD_DEPS = [
    "cmake", "gcc", "gcc-c++", "pkg-config",
    "libX11-devel", "libXfixes-devel", "libXi-devel", "libXScrnSaver-devel",
    "wayland-devel", "wayland-protocols-devel", "libxkbcommon-devel",
    "mesa-libEGL-devel", "mesa-libGL-devel",
    "fontconfig-devel", "freetype-devel",
    "spice-protocol", "nettle-devel", "zlib-devel",
    "libsamplerate-devel", "libpipewire-devel",
]


def step_looking_glass(state: WizardState) -> tuple[bool, str]:
    """
    Build the Looking Glass client from source inside a disposable toolbox
    container and install it to /usr/local/bin on the host.

    Only runs when gpu_passthrough is True and install_looking_glass is True.

    The KVMFR kernel module is managed separately.

    DISCLAIMER: The Looking Glass host application (for Windows) must be
    downloaded and installed manually inside the gaming VM.
    Pre-built Windows host binaries: https://looking-glass.io/downloads
    The host application version must match the client (B7).
    """
    if not (state.gpu_passthrough and state.selected_gpu
            and state.install_looking_glass):
        return True, "Looking Glass not requested — skipped."

    if Path(_LG_CLIENT_DEST).exists():
        _lg_inject_shmem(state)
        return True, "Looking Glass client already installed — skipped."

    ok, msg = _lg_build_in_toolbox()
    if not ok:
        return False, msg

    _lg_inject_shmem(state)
    return (
        True,
        "Looking Glass client built and installed. "
        "Download the matching Windows host application (B7) from "
        "https://looking-glass.io/downloads and install it inside the gaming VM."
    )


def _lg_build_in_toolbox() -> tuple[bool, str]:
    """
    Build Looking Glass B7 client inside a disposable Fedora toolbox container.
    All build deps are confined to the container — the immutable host is untouched.
    Binary is written to /usr/local/bin/ which persists across rpm-ostree upgrades.
    """
    import shutil

    if not shutil.which("toolbox"):
        return False, (
            "toolbox not found. Run: rpm-ostree install toolbox && systemctl reboot"
        )

    _run(["toolbox", "rm", "-f", _LG_TOOLBOX_NAME], timeout=30)

    ok, msg = _run(
        ["toolbox", "-y", "create", "--image",
         "registry.fedoraproject.org/fedora:latest",
         _LG_TOOLBOX_NAME],
        timeout=120,
    )
    if not ok:
        return False, "toolbox create: " + msg

    def tb(*cmd, timeout=60):
        return _run(
            ["toolbox", "-y", "run", "--container", _LG_TOOLBOX_NAME, "--", *cmd],
            timeout=timeout,
        )

    ok, msg = tb("sudo", "dnf", "install", "-y", *_LG_BUILD_DEPS, timeout=300)
    if not ok:
        _run(["toolbox", "rm", "-f", _LG_TOOLBOX_NAME], timeout=30)
        return False, "dnf build deps: " + msg

    ok, msg = tb(
        "curl", "-fL", "--retry", "3",
        "-o", _LG_SOURCE_TAR, _LG_SOURCE_URL,
        timeout=120,
    )
    if not ok:
        _run(["toolbox", "rm", "-f", _LG_TOOLBOX_NAME], timeout=30)
        return False, "source download: " + msg

    ok, msg = tb(
        "bash", "-c",
        "mkdir -p " + _LG_BUILD_DIR
        + " && tar -xzf " + _LG_SOURCE_TAR
        + " -C " + _LG_BUILD_DIR + " --strip-components=1",
        timeout=60,
    )
    if not ok:
        _run(["toolbox", "rm", "-f", _LG_TOOLBOX_NAME], timeout=30)
        return False, "extract: " + msg

    ok, msg = tb(
        "bash", "-c",
        "mkdir -p " + _LG_BUILD_DIR + "/client/build"
        + " && cd " + _LG_BUILD_DIR + "/client/build"
        + " && cmake .. -DENABLE_WAYLAND=ON -DENABLE_X11=OFF"
        + " -DCMAKE_BUILD_TYPE=Release",
        timeout=120,
    )
    if not ok:
        _run(["toolbox", "rm", "-f", _LG_TOOLBOX_NAME], timeout=30)
        return False, "cmake: " + msg

    ok, msg = tb(
        "bash", "-c",
        "cd " + _LG_BUILD_DIR + "/client/build && make -j$(nproc)",
        timeout=600,
    )
    if not ok:
        _run(["toolbox", "rm", "-f", _LG_TOOLBOX_NAME], timeout=30)
        return False, "make: " + msg

    bin_src = _LG_BUILD_DIR + "/client/build/looking-glass-client"
    ok, msg = _run(
        ["pkexec", "bash", "-c",
         "toolbox run --container " + _LG_TOOLBOX_NAME
         + " -- cat " + bin_src
         + " > " + _LG_CLIENT_DEST
         + " && chmod 755 " + _LG_CLIENT_DEST],
        timeout=60,
    )
    if not ok:
        _run(["toolbox", "rm", "-f", _LG_TOOLBOX_NAME], timeout=30)
        return False, "install binary: " + msg

    if not Path(_LG_CLIENT_DEST).exists():
        _run(["toolbox", "rm", "-f", _LG_TOOLBOX_NAME], timeout=30)
        return False, "Binary missing after install."

    _run(["toolbox", "rm", "-f", _LG_TOOLBOX_NAME], timeout=60)
    return True, "Looking Glass client installed to " + _LG_CLIENT_DEST + "."


def _lg_inject_shmem(state: WizardState) -> None:
    """Inject ivshmem-plain shmem device into gaming-vm XML for Looking Glass."""
    import subprocess as _sp

    result = _sp.run(
        _VIRSH + ["dumpxml", "gaming-vm"],
        capture_output=True, text=True,
    )
    if result.returncode != 0 or "looking-glass" in result.stdout:
        return

    shmem_size = str(_LG_SHMEM_SIZE_MB)
    shmem = (
        "\n    <shmem name='looking-glass'>"
        "\n      <model type='ivshmem-plain'/>"
        "\n      <size unit='M'>" + shmem_size + "</size>"
        "\n    </shmem>"
    )
    new_xml = result.stdout.replace("</devices>", shmem + "\n  </devices>", 1)

    import tempfile as _tmp, os as _os
    with _tmp.NamedTemporaryFile(
        mode="w", suffix=".xml", prefix="bulwark-gaming-lg-", delete=False
    ) as f:
        f.write(new_xml)
        tmp = f.name
    _run(_VIRSH + ["define", tmp])
    _os.unlink(tmp)


# ---------------------------------------------------------------------------
# Step 10 — Permanent host routing via systemd
# ---------------------------------------------------------------------------
# The host needs a default route through sys-firewall's AppVM-facing interface
# (10.10.1.254 on bulwark-appvms) to reach the VM network and for AppVMs to
# be able to communicate back to the host.
#
# We cannot use /etc/sysconfig/network-scripts or NetworkManager for this
# because the route depends on the libvirt network bridge (bulwark-avm) which
# doesn't exist until libvirtd starts. A dedicated systemd service that runs
# After=libvirtd.service is the correct hook.

_HOST_ROUTE_SERVICE = """[Unit]
Description=BulwarkOS host route via sys-firewall
Documentation=https://github.com/connorethanjay/bulwarkOS
# Wait for libvirtd to have started the bulwark-appvms bridge
After=network-online.target libvirtd.service
Wants=network-online.target

[Service]
Type=oneshot
RemainAfterExit=yes
# Add default route through sys-firewall's LAN IP on the appvms bridge.
# The bridge interface is named bulwark-avm by libvirt (derived from the
# network name bulwark-appvms with the 'bulwark-' prefix).
# Route all traffic (0.0.0.0/0) through sys-firewall on the appvms bridge.
# "default" is an alias for 0.0.0.0/0 in iproute2; we use it explicitly.
# Wait up to 30s for the bulwark-avm bridge (created by libvirtd)
ExecStartPre=/bin/sh -c 'i=0; while [ $i -lt 30 ] && ! ip link show bulwark-avm >/dev/null 2>&1; do sleep 1; i=$((i+1)); done'
ExecStart=/usr/sbin/ip route replace 0.0.0.0/0 via 10.10.1.254 dev bulwark-avm
ExecStop=/usr/sbin/ip route del 0.0.0.0/0 via 10.10.1.254 dev bulwark-avm
Restart=on-failure
RestartSec=5

[Install]
WantedBy=multi-user.target
"""

_HOST_ROUTE_SERVICE_PATH = "/etc/systemd/system/bulwarkos-host-route.service"


def step_host_network(state: WizardState) -> tuple[bool, str]:
    """
    Writes a systemd service that adds a permanent host default route through
    sys-firewall (10.10.1.254) on the bulwark-avm bridge, and enables it.
    Skipped if the service is already installed with the correct content.
    """
    import tempfile

    errors: list[str] = []

    # Skip if service already installed with correct content
    try:
        existing = Path(_HOST_ROUTE_SERVICE_PATH).read_text()
        if existing.strip() == _HOST_ROUTE_SERVICE.strip():
            ok_e, _ = _run(
                ["systemctl", "is-enabled", "bulwarkos-host-route.service"],
                timeout=5,
            )
            if ok_e:
                return True, "Host route service already installed and enabled — skipped."
    except OSError:
        pass

    # Write service unit to a temp file the wizard can write, then move it
    try:
        with tempfile.NamedTemporaryFile(
            mode="w", suffix=".service",
            prefix="bulwarkos-host-route-",
            delete=False,
        ) as tmp:
            tmp.write(_HOST_ROUTE_SERVICE)
            tmp_path = tmp.name
    except OSError as e:
        return False, f"Failed to write host-route service file: {e}"

    ok, msg = _run(
        ["pkexec", "mv", tmp_path, _HOST_ROUTE_SERVICE_PATH], timeout=10
    )
    if not ok:
        try: os.unlink(tmp_path)
        except OSError: pass
        return False, f"Failed to install host-route service: {msg}"

    _run(["pkexec", "chmod", "644", _HOST_ROUTE_SERVICE_PATH], timeout=10)

    # Reload systemd so it sees the new unit
    ok, msg = _run(["pkexec", "systemctl", "daemon-reload"], timeout=15)
    if not ok:
        errors.append(f"daemon-reload: {msg}")

    # Enable the service so it starts automatically on boot
    ok, msg = _run(
        ["pkexec", "systemctl", "enable", "bulwarkos-host-route.service"],
        timeout=15,
    )
    if not ok:
        errors.append(f"systemctl enable host-route: {msg}")

    # Start immediately — route is active this session without a reboot
    _run(["pkexec", "systemctl", "start",
          "bulwarkos-host-route.service"], timeout=45)

    if errors:
        return False, "; ".join(errors)
    return True, "Host route service installed, enabled, and started."


# ---------------------------------------------------------------------------
# Step 11 — Write state file (marks setup as complete)
# ---------------------------------------------------------------------------

def step_mark_complete(state: WizardState) -> tuple[bool, str]:
    """
    Writes /var/lib/bulwarkos/.setup-complete to mark setup as done.

    /var/lib/ is root-owned, so all three operations — creating the directory,
    writing the file, and locking down permissions — go through pkexec.
    The wizard process itself never needs write access to /var/lib/.
    """
    import tempfile

    state_dir = Path(STATE_FILE).parent
    content = (
        f"# BulwarkOS setup completed\n"
        f"cpu_vendor={state.hardware.cpu_vendor}\n"
        f"gpu_passthrough={'1' if state.gpu_passthrough else '0'}\n"
        f"appvms={','.join(state.selected_appvms)}\n"
    )

    # 1. Create /var/lib/bulwarkos/ if it does not exist
    ok, msg = _run(
        ["pkexec", "mkdir", "-p", str(state_dir)],
        timeout=10,
    )
    if not ok:
        return False, f"Could not create state directory {state_dir}: {msg}"

    # 2. Write content to a temp file the wizard CAN write to
    try:
        with tempfile.NamedTemporaryFile(
            mode="w",
            suffix=".tmp",
            prefix="bulwark-state-",
            delete=False,
        ) as tmp:
            tmp.write(content)
            tmp_path = tmp.name
    except OSError as e:
        return False, f"Could not write temporary state file: {e}"

    # 3. Move the temp file into place as root
    ok, msg = _run(
        ["pkexec", "mv", tmp_path, STATE_FILE],
        timeout=10,
    )
    if not ok:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        return False, f"Could not install state file at {STATE_FILE}: {msg}"

    # 4. Lock down permissions — readable by root only.
    #    The ConditionPathExists= check in the systemd unit only needs existence,
    #    not readability, so 600 is fine and prevents unprivileged tampering.
    _run(["pkexec", "chmod", "600", STATE_FILE], timeout=10)
    _run(["pkexec", "chown", "root:root", STATE_FILE], timeout=10)

    return True, f"State file written to {STATE_FILE}."

# ---------------------------------------------------------------------------
# Orchestrator — runs all steps, reports progress via callback
# ---------------------------------------------------------------------------

StepCallback = Callable[[str, str, bool], None]
# callback(step_id, message, success)

STEPS: list[tuple[str, str, Callable]] = [
    ("kargs",      "Writing kernel arguments",              step_kargs),
    ("modprobe",   "Writing VFIO modprobe config",          step_modprobe),
    ("initramfs",  "Rebuilding initramfs",                  step_initramfs),
    # qemu.conf must be set and libvirtd restarted before virsh commands are run
    ("qemu_conf",  "Configuring QEMU user/group",           step_configure_qemu),
    # Networks must be defined before VMs
    ("networks",   "Defining libvirt networks",             step_define_networks),
    # Generate dedicated SSH keypair before provisioning
    ("ssh_key",    "Generating infrastructure SSH keypair",   step_generate_ssh_key),
    # Images must exist on disk before virsh define — libvirt validates paths
    ("images",     "Downloading and provisioning images",   step_provision_images),
    ("vms",        "Registering VM definitions",            step_define_vms),
    ("looking_glass", "Installing Looking Glass",           step_looking_glass),
    ("host_net",   "Configuring host network routing",       step_host_network),
    ("complete",   "Marking setup complete",                step_mark_complete),
]


def run_apply(state: WizardState, on_step: StepCallback) -> bool:
    """
    Runs all apply steps in order.
    Calls on_step(step_id, message, success) after each step.
    Returns True if all steps succeeded.
    """
    all_ok = True
    for step_id, label, fn in STEPS:
        on_step(step_id, f"{label}…", None)  # None = in-progress
        try:
            ok, msg = fn(state)
        except Exception as exc:
            ok, msg = False, f"Unexpected error: {exc}"
        if not ok:
            state.apply_errors.append(f"{label}: {msg}")
            all_ok = False
        on_step(step_id, msg, ok)
    return all_ok
